Widget _duoPanelRail(JsAppPanelChrome chrome, double width) {
  return Positioned(
    top: FaDuoControlRail.topOf(context),
    right: 0,
    bottom: 0,
    width: width,
    child: FaDuoControlRail(
      key: const ValueKey('appChromeActions'),
      actions: _panelChromeActions(chrome, width),
