void _onAppPopInvoked(bool didPop, bool backRegistered) {
  if (didPop) return;
  final chrome = widget.panelChrome;
  if (chrome != null && !backRegistered) {
    chrome.onClose();
  } else {
    _forwardBackToApp();
  }
}

Widget _appCanvas(ThemeData theme, bool fullChrome, double topInset) {
  return Padding(
